mapper.select:
WITH MONI_TMS AS /* Batch_Sql.selectBatchList 배치 리스트 조회 */ ( SELECT B.STACT_FIN_YM , A.STACT_ACT_ID /* 결산활동ID */ , A.BAT_ID /* 배치ID */ , B.STR_DTM /* 시작일시 */ FROM S_FI.TB_IFIMTF01 A /* 결산Activity관리 */ INNER JOIN S_FI.TB_IFIMTD01 B /* 결산Monitoring내역관리 */ ON A.STACT_ACT_ID = B.STACT_ACT_ID AND A.USE_YN = 'Y' AND A.BAT_ID IS NOT NULL AND B.STACT_FIN_YM = #{finYm} AND B.FIN_TMS = (SELECT MAX(FIN_TMS) FROM S_FI.TB_IFIMTD01 WHERE STACT_FIN_YM = #{finYm}) ), BAT_LIST AS( SELECT A.STND_YMD /* 기준일자 */ , A.BAT_WK_ID /* 배치작업ID */ , A.SP_ID /* SP ID */ , A.REG_DTM /* 등록일시 */ , 'S' AS RST_CD /* 결과코드 */ FROM S_MG.TB_IMGDAL02 A /* 배치실행결과로그 */ INNER JOIN MONI_TMS B ON A.BAT_WK_ID = B.BAT_ID
AND A.REG_DTM >= B.STR_DTM
WHERE 1 = 1 AND A.SP_ID NOT LIKE '%_TRUN_%' AND A.SP_ID NOT LIKE '%DECM_TAB%' AND A.SP_ID NOT LIKE '%COMP_TAB%'
AND A.STND_YMD LIKE #{finYm}||'%'
AND A.STND_YMD = #{finYm}
UNION ALL SELECT A.STND_YMD /* 기준일자 */ , A.BAT_WK_ID /* 배치작업ID */ , A.SP_ID /* SP ID */ , A.REG_DTM /* 등록일시 */ , 'E' AS RST_CD /* 결과코드 */ FROM S_MG.TB_IMGDAL03 A /* 배치실행에러로그 */ INNER JOIN MONI_TMS B ON A.BAT_WK_ID = B.BAT_ID
AND A.REG_DTM >= B.STR_DTM
WHERE 1 = 1 AND A.SP_ID NOT LIKE '%_TRUN_%' AND A.SP_ID NOT LIKE '%DECM_TAB%' AND A.SP_ID NOT LIKE '%COMP_TAB%'
AND A.STND_YMD LIKE #{finYm}||'%'
AND A.STND_YMD = #{finYm}
), BAT_LAST_LST AS ( SELECT L.BAT_WK_ID /* 배치작업ID */ , CASE WHEN L.ERR_CNT > 0 THEN 'E' ELSE 'F' END AS PRG_STAT /* 프로그램 시작 */ , L.REG_DTM AS FIN_TOD /* 등록일시 */ FROM ( SELECT A.BAT_WK_ID /* 배치작업ID */ , SUM(CASE WHEN A.RST_CD = 'S' THEN 1 ELSE 0 END) AS SUC_CNT /* 성공건수 */ , SUM(CASE WHEN A.RST_CD = 'E' THEN 1 ELSE 0 END) AS ERR_CNT /* 실패건수 */ , MAX(A.REG_DTM) AS REG_DTM FROM BAT_LIST A , (SELECT BAT_WK_ID, SP_ID, MAX(REG_DTM) AS REG_DTM FROM BAT_LIST GROUP BY BAT_WK_ID, SP_ID) B WHERE 1 = 1 AND A.BAT_WK_ID = B.BAT_WK_ID AND A.SP_ID = B.SP_ID AND A.REG_DTM = B.REG_DTM GROUP BY A.BAT_WK_ID ) L ), BAT_PRG_STAT AS ( SELECT ROW_NUMBER() OVER (PARTITION BY A.BAT_WK_ID ORDER BY A.REG_DTM DESC) AS RW , A.BAT_WK_ID , A.BAT_PRG_STAT_CD , C.CDC_VAL_NM AS PRG_STAT_NM FROM S_MG.TB_IMGDAL05 A /* 배치실행로그 */ INNER JOIN MONI_TMS B ON A.BAT_WK_ID = B.BAT_ID AND A.FIN_YM = B.STACT_FIN_YM
AND A.REG_DTM >= B.STR_DTM
INNER JOIN EAGLE.TB_CISSM02 C /* 코드관리 */ ON C.STNRD_TRMN_ENG_NM = 'BAT_PRG_STAT_CD' AND A.BAT_PRG_STAT_CD = C.CDC_VALT WHERE 1 = 1 ) SELECT A.BAT_ID AS BAT_ID /* 배치ID */ , NVL(STA.PRG_STAT_NM, '수행전') AS BAT_STATUS /* 배치 상태 */ , NVL(B.BAT_EXPLN, '') AS BAT_EXPLN /* 배치설명 */ FROM S_FI.TB_IFIMTF01 A /* 결산Activity관리 */ INNER JOIN S_MG.TB_IMGSYF08 B /* 배치정보관리기본 */ ON A.BAT_ID = B.BAT_ID LEFT OUTER JOIN BAT_LAST_LST C ON A.BAT_ID = C.BAT_WK_ID LEFT OUTER JOIN BAT_PRG_STAT STA ON A.BAT_ID = STA.BAT_WK_ID AND STA.RW = 1 WHERE 1 = 1 AND A.STACT_ACT_LVL = 4
AND A.STACT_ACT_UPP_ID = #{actUppId} AND A.BAT_ID = #{batchId}
AND A.STACT_ACT_UPP_ID = #{actUppId}
ORDER BY A.STACT_ACT_SEQ

mapper.insert:

INSERT /* Batch_Sql.insertBatchGridInfo 배치관리 저장  */
INTO S_MG.TB_IMGSYF08	/* 배치정보관리기본 */
( 
	 PGM_ID		/* 프로그램ID */
	,BAT_ID		/* 배치ID */
	,BAT_NM		/* 배치명 */
	,BAT_EXPLN	/* 배치설명 */
	,I17_BUSN_SC_CD	/* 업무구분코드 */
	,USE_YN		/* 사용여부 */
	,REG_DTM	/* 등록자사번 */
	,REGNT_ENO	/* 등록일시 */
	,TRT_DTM	/* 처리자사번 */
	,TRTR_ENO	/* 처리일시 */
)
VALUES
( 	
	(SELECT LPAD(NVL(MAX(PGM_ID),0)+1,5,0) FROM S_MG.TB_IMGSYF08) /* 배치정보관리기본 */
	,#{batId}
	,#{batId}
	,#{batExpln}
	,#{busnScCd}
	,#{useYn}
	,CURRENT_TIMESTAMP
	,#{regntEno}
	,CURRENT_TIMESTAMP
	,#{trtrEno}
)

mapper.update:
UPDATE /* Batch_Sql.updateBatchGridInfo 배치관리 저장  */
   S_MG.TB_IMGSYF08	/* 배치정보관리기본 */
   SET BAT_ID		= #{batId}	
   	 , BAT_NM 		= #{batId}
	 , BAT_EXPLN 	= #{batExpln}
	 , I17_BUSN_SC_CD 	= #{busnScCd}
	 , USE_YN 		= #{useYn}
	 , TRTR_ENO 	= #{trtrEno}
	 , TRT_DTM 		= CURRENT_TIMESTAMP
 WHERE PGM_ID  		= #{pgmId}

mapper.delete:
DELETE /* Batch_Sql.deleteBatchGridInfo 배치관리 삭제  */
  FROM S_MG.TB_IMGSYF08 /* 배치정보관리기본 */
 WHERE PGM_ID 		= #{pgmId}

mapper.insert:

INSERT /* Batch_Sql.insertParamGridInfo 파라미터관리 저장  */
INTO S_MG.TB_IMGSYF09	/* 배치파라미터관리기본 */
(
	 PGM_ID				/* 프로그램ID */
	,ITM_ID				/* 항목ID */
	,BAT_ID				/* 배치ID */
	,INPT_PRMTR_ID		/* 입력파라미터ID */
	,INPT_PRMTR_NM		/* 입력파라미터명 */
	,INPT_PRMTR_EXPLN	/* 입력파라미터설명 */
	,INPT_PRMTR_TYP_CD	/* 입력파라미터유형코드 */
	,PRMTR_INPT_SEQ		/* 파라미터입력순서 */
	,USE_YN				/* 사용여부 */
	,REG_DTM			/* 등록자사번 */
	,REGNT_ENO			/* 등록일시 */
	,TRT_DTM			/* 처리자사번 */
	,TRTR_ENO			/* 처리일시 */
)
VALUES
(
	 #{pgmId}
	,(SELECT LPAD(NVL(MAX(ITM_ID),0)+1,5,0) FROM S_MG.TB_IMGSYF09 /* 배치파라미터관리기본 */ WHERE PGM_ID = #{pgmId})
	,#{batId}
	,#{inptPrmtrId}
	,#{inptPrmtrNm}
	,#{inptPrmtrExpln}
	,#{inptPrmtrTypCd}
	,#{prmtrInptSeq}
	,#{useYn}
	,CURRENT_TIMESTAMP
	,#{regntEno}
	,CURRENT_TIMESTAMP
	,#{trtrEno}
)

mapper.update:
UPDATE /* Batch_Sql.updateParamGridInfo 파라미터관리 저장  */ 
   S_MG.TB_IMGSYF09	/* 배치파라미터관리기본 */
   SET INPT_PRMTR_ID 		= #{inptPrmtrId}
	 , INPT_PRMTR_NM 		= #{inptPrmtrNm}
	 , INPT_PRMTR_EXPLN 	= #{inptPrmtrExpln}
	 , INPT_PRMTR_TYP_CD 	= #{inptPrmtrTypCd}
	 , PRMTR_INPT_SEQ 		= #{prmtrInptSeq}
	 , USE_YN 				= #{useYn}
	 , TRTR_ENO 			= #{trtrEno}
	 , TRT_DTM 				= CURRENT_TIMESTAMP
 WHERE PGM_ID 				= #{pgmId}				
   AND ITM_ID 				= #{itmId}

mapper.delete:
DELETE /* Batch_Sql.deleteParamGridInfo 파라미터관리 삭제  */  
  FROM S_MG.TB_IMGSYF09	/* 배치파라미터관리기본 */
 WHERE PGM_ID 		 		= #{pgmId} 
   AND ITM_ID 		 		= #{itmId}

DELETE /* Batch_Sql.deleteParamInfobyId 파라미터관리 삭제  */ 
  FROM S_MG.TB_IMGSYF09  /* 배치파라미터관리기본 */
 WHERE PGM_ID 				= #{pgmId}
